<?php
 namespace Pterodactyl\Models\Dezerx; use Pterodactyl\Models\Model; use Pterodactyl\Models\Server; use Illuminate\Database\Eloquent\Relations\BelongsTo; class RustWipeRun extends Model { public const RESOURCE_NAME = 'rust_wipe_run'; public const PENDING = 'pending'; public const STOPPING = 'stopping'; public const WIPING = 'wiping'; public const STARTING = 'starting'; public const DONE = 'done'; public const FAILED = 'failed'; public const CANCELLED = 'cancelled'; public const MISSED = 'missed'; public const ACTIVE = [self::PENDING, self::STOPPING, self::WIPING, self::STARTING]; protected $table = 'dezerx_rust_wipe_runs'; protected $guarded = ['id']; protected $casts = [ 'server_id' => 'int', 'wipe_id' => 'int', 'settings' => 'array', 'scheduled_for' => 'int', 'warned' => 'array', 'was_running' => 'bool', 'stop_sent_at' => 'int', 'killed' => 'bool', 'deleted' => 'array', 'started_at' => 'int', 'finished_at' => 'int', 'user_id' => 'int', ]; public static array $validationRules = [ 'server_id' => 'required|int|exists:servers,id', 'name' => 'required|string|max:64', 'trigger' => 'required|string|in:schedule,manual', 'status' => 'required|string', 'scheduled_for' => 'required|int', ]; public function isActive(): bool { return in_array($this->status, self::ACTIVE, true); } public function server(): BelongsTo { return $this->belongsTo(Server::class); } public function wipe(): BelongsTo { return $this->belongsTo(RustWipe::class, 'wipe_id'); } } 